  1→import {
  2→  Inject,
  3→  Injectable,
  4→  Logger,
  5→  UnauthorizedException,
  6→  BadRequestException,
  7→  ForbiddenException,
  8→  OnModuleDestroy,
  9→} from '@nestjs/common';
 10→import { InjectRepository } from '@nestjs/typeorm';
 11→import { ConfigService } from '@nestjs/config';
 12→import { Repository, IsNull, Not } from 'typeorm';
 13→import { createECDH, createHash, timingSafeEqual } from 'crypto';
 14→import * as jose from 'jose';
 15→import * as argon2 from 'argon2';
 16→import Redis from 'ioredis';
 17→import { User } from './entities/user.entity';
 18→import { AuthMethod } from './entities/auth-method.entity';
 19→import { RefreshToken } from './entities/refresh-token.entity';
 20→import { PinnedCid } from '../vault/entities/pinned-cid.entity';
 21→import { IPFS_PROVIDER, IpfsProvider } from '../ipfs/providers/ipfs-provider.interface';
 22→import { JwtIssuerService } from './services/jwt-issuer.service';
 23→import { TokenService } from './services/token.service';
 24→import { SiweService } from './services/siwe.service';
 25→import { parseSiweMessage } from 'viem/siwe';
 26→import { LoginDto, LoginServiceResult } from './dto/login.dto';
 27→import { RefreshServiceResult, LogoutResponseDto } from './dto/token.dto';
 28→import { LinkMethodDto, AuthMethodResponseDto } from './dto/link-method.dto';
 29→
 30→@Injectable()
 31→export class AuthService implements OnModuleDestroy {
 32→  private readonly logger = new Logger(AuthService.name);
 33→  private readonly redis: Redis;
 34→
 35→  constructor(
 36→    private configService: ConfigService,
 37→    private jwtIssuerService: JwtIssuerService,
 38→    private tokenService: TokenService,
 39→    private siweService: SiweService,
 40→    @InjectRepository(User)
 41→    private userRepository: Repository<User>,
 42→    @InjectRepository(AuthMethod)
 43→    private authMethodRepository: Repository<AuthMethod>,
 44→    @InjectRepository(RefreshToken)
 45→    private refreshTokenRepository: Repository<RefreshToken>,
 46→    @InjectRepository(PinnedCid)
 47→    private pinnedCidRepository: Repository<PinnedCid>,
 48→    @Inject(IPFS_PROVIDER)
 49→    private ipfsProvider: IpfsProvider
 50→  ) {
 51→    this.redis = new Redis({
 52→      host: configService.get('REDIS_HOST', 'localhost'),
 53→      port: configService.get<number>('REDIS_PORT', 6379),
 54→      password: configService.get('REDIS_PASSWORD', undefined),
 55→      lazyConnect: true,
 56→    });
 57→  }
 58→
 59→  async onModuleDestroy(): Promise<void> {
 60→    await this.redis.quit();
 61→  }
 62→
 63→  async login(loginDto: LoginDto): Promise<LoginServiceResult> {
 64→    // 1. Verify CipherBox-issued JWT.
 65→    // All auth methods now go through: CipherBox identity provider -> Core Kit loginWithJWT -> /auth/login.
 66→    const payload = await this.verifyCipherBoxJwt(loginDto.idToken);
 67→
 68→    // 2. Find or create user
 69→    let user = await this.userRepository.findOne({
 70→      where: { publicKey: loginDto.publicKey },
 71→    });
 72→
 73→    // 2b. Placeholder publicKey resolution for Core Kit identity provider.
 74→    //
 75→    // Two scenarios need resolution:
 76→    //
 77→    // A) FIRST LOGIN completion: User was created with a placeholder publicKey
 78→    //    ('pending-core-kit-{verifierId}') during identity token issuance.
 79→    //    After Core Kit loginWithJWT, the client calls /auth/login with the
 80→    //    REAL publicKey. Find the placeholder user and update their publicKey.
 81→    //
 82→    // B) REQUIRED_SHARE temp auth: MFA is enabled but the new device can't
 83→    //    reconstruct the Core Kit key (missing device factor). The client
 84→    //    sends a placeholder publicKey to get a temp access token for the
 85→    //    device approval bulletin board. The user already has a REAL publicKey
 86→    //    from their first login, so we look them up by identity (authMethod
 87→    //    identifierHash) instead of by publicKey.
 88→    if (!user) {
 89→      const verifierId = payload.verifierId || payload.sub;
 90→
 91→      if (verifierId) {
 92→        // A) Check for user with placeholder publicKey (first login completion)
 93→        const placeholderUser = await this.userRepository.findOne({
 94→          where: { publicKey: `pending-core-kit-${verifierId}` },
 95→        });
 96→        if (placeholderUser) {
 97→          this.logger.log(`Resolving placeholder publicKey for user ${placeholderUser.id}`);
 98→          // Only update publicKey if the incoming key is a real one (not another placeholder)
 99→          if (!loginDto.publicKey.startsWith('pending-core-kit-')) {
100→            placeholderUser.publicKey = loginDto.publicKey;
101→            user = await this.userRepository.save(placeholderUser);
102→          } else {
103→            user = placeholderUser;
104→          }
105→        }
106→      }
107→
108→      // B) REQUIRED_SHARE temp auth: user already completed first login (has real
109→      //    publicKey), so no placeholder row exists. Look up directly by userId
110→      //    from the JWT sub — works for all auth method types (email, Google, wallet).
111→      if (!user && payload.sub && loginDto.publicKey.startsWith('pending-core-kit-')) {
112→        const existingUser = await this.userRepository.findOne({
113→          where: { id: payload.sub },
114→        });
115→        if (existingUser) {
116→          this.logger.log(
117→            `REQUIRED_SHARE temp auth: found existing user ${existingUser.id} by userId`
118→          );
119→          user = existingUser;
120→        }
121→      }
122→    }
123→
124→    const isNewUser = !user;
125→    if (!user) {
126→      user = await this.userRepository.save({
127→        publicKey: loginDto.publicKey,
128→      });
129→    }
130→
131→    // 3. Find or create auth method
132→    // The identity controller already created the auth method
133→    // (with the correct type: 'google', 'email', or 'wallet'). Look up by
134→    // userId + identifierHash to avoid creating duplicates with a hardcoded type.
135→    let authMethod: AuthMethod | null;
136→
137→    const identifier = payload.email || payload.sub;
138→    if (!identifier) {
139→      this.logger.warn('CipherBox JWT missing both email and sub claims');
140→      throw new UnauthorizedException('Invalid identity token: missing identifier');
141→    }
142→    const identifierHash = this.siweService.hashIdentifier(identifier);
143→    authMethod = await this.authMethodRepository.findOne({
144→      where: { userId: user.id, identifierHash },
145→    });
146→    if (!authMethod) {
147→      // Fallback: find any auth method for this user (identity controller should have created one)
148→      authMethod = await this.authMethodRepository.findOne({
149→        where: { userId: user.id },
150→      });
151→    }
152→    if (!authMethod) {
153→      // Safety net: create auth method if identity controller didn't (shouldn't happen in practice)
154→      // All logins go through loginType='corekit' now, but infer type from identifier format
155→      const inferredType = identifier.startsWith('0x') ? 'wallet' : 'email';
156→      const display =
157→        inferredType === 'wallet'
158→          ? this.siweService.truncateWalletAddress(identifier)
159→          : this.siweService.truncateEmail(identifier);
160→      authMethod = await this.authMethodRepository.save({
161→        userId: user.id,
162→        type: inferredType,
163→        identifier: identifierHash,
164→        identifierHash,
165→        identifierDisplay: display,
166→      });
167→    }
168→
169→    // 4. Update last used timestamp
170→    authMethod.lastUsedAt = new Date();
171→    await this.authMethodRepository.save(authMethod);
172→
173→    // 5. Create tokens
174→    // REQUIRED_SHARE temp auth: issue scoped, non-refreshable tokens that only
175→    // grant access to the device-approval bulletin board. The new device will
176→    // do a second /auth/login with the real publicKey after key reconstruction.
177→    const isTempAuth = loginDto.publicKey.startsWith('pending-core-kit-') && !isNewUser;
178→    const tokens = await this.tokenService.createTokens(
179→      user.id,
180→      user.publicKey,
181→      isTempAuth ? { scope: ['device-approval'], skipRefreshToken: true } : undefined
182→    );
183→
184→    return {
185→      accessToken: tokens.accessToken,
186→      refreshToken: tokens.refreshToken,
187→      isNewUser,
188→    };
189→  }
190→
191→  /**
192→   * Verify a CipherBox-issued JWT for Core Kit login flow.
193→   * Since we are the identity provider, we verify against our own JWKS.
194→   */
195→  private async verifyCipherBoxJwt(
196→    idToken: string
197→  ): Promise<{ sub?: string; verifierId?: string; email?: string }> {
198→    try {
199→      const jwksData = this.jwtIssuerService.getJwksData();
200→      const jwks = jose.createLocalJWKSet(jwksData);
201→      const { payload } = await jose.jwtVerify(idToken, jwks, {
202→        issuer: 'cipherbox',
203→        audience: 'web3auth',
204→        algorithms: ['RS256'],
205→      });
206→      return {
207→        sub: payload.sub,
208→        verifierId: payload.sub,
209→        email: payload.email as string | undefined,
210→      };
211→    } catch (error) {
212→      this.logger.warn(
213→        `CipherBox JWT verification failed: ${error instanceof Error ? error.message : 'unknown'}`
214→      );
215→      throw new UnauthorizedException('Invalid CipherBox identity token');
216→    }
217→  }
218→
219→  async refresh(
220→    refreshToken: string,
221→    userId: string,
222→    publicKey: string
223→  ): Promise<RefreshServiceResult> {
224→    const tokens = await this.tokenService.rotateRefreshToken(refreshToken, userId, publicKey);
225→
226→    return {
227→      accessToken: tokens.accessToken,
228→      refreshToken: tokens.refreshToken,
229→    };
230→  }
231→
232→  async logout(userId: string): Promise<LogoutResponseDto> {
233→    await this.tokenService.revokeAllUserTokens(userId);
234→    return { success: true };
235→  }
236→
237→  /**
238→   * Permanently delete a user account and all associated data.
239→   *
240→   * 1. Unpins all IPFS content from the local Kubo node (best-effort)
241→   * 2. Deletes the user row — ON DELETE CASCADE handles cleanup of
242→   *    auth_methods, refresh_tokens, vaults, pinned_cids, folder_ipns,
243→   *    ipns_republish_schedule, shares, share_keys, and share_invites.
244→   */
245→  async deleteAccount(userId: string): Promise<{ success: boolean }> {
246→    // Fetch all pinned CIDs before cascade deletes the records
247→    const pinnedCids = await this.pinnedCidRepository.find({
248→      where: { userId },
249→      select: ['cid'],
250→    });
251→
252→    // Unpin all content from Kubo (best-effort, don't block deletion on failure)
253→    if (pinnedCids.length > 0) {
254→      const results = await Promise.allSettled(
255→        pinnedCids.map((pin) => this.ipfsProvider.unpinFile(pin.cid))
256→      );
257→      const failed = results.filter((r) => r.status === 'rejected').length;
258→      this.logger.log(
259→        `Unpinned ${pinnedCids.length - failed}/${pinnedCids.length} CIDs for user ${userId}` +
260→          (failed > 0 ? ` (${failed} failed)` : '')
261→      );
262→    }
263→
264→    // Delete user row — cascade handles all related DB records
265→    const result = await this.userRepository.delete(userId);
266→    if (result.affected === 0) {
267→      throw new BadRequestException('Account not found');
268→    }
269→    this.logger.log(`Account deleted: userId=${userId}`);
270→    return { success: true };
271→  }
272→
273→  /**
274→   * Refresh tokens by searching for the matching refresh token across all users.
275→   * This allows refresh without requiring the (possibly expired) access token.
276→   */
277→  async refreshByToken(refreshToken: string): Promise<RefreshServiceResult> {
278→    // Find candidate tokens by prefix for O(1) lookup instead of O(N) Argon2 scan
279→    const prefix = refreshToken.substring(0, 16);
280→    const tokens = await this.refreshTokenRepository.find({
281→      where: {
282→        tokenPrefix: prefix,
283→        revokedAt: IsNull(),
284→      },
285→      relations: ['user'],
286→    });
287→
288→    // Find matching token by verifying against hashes
289→    let validToken: RefreshToken | null = null;
290→    for (const token of tokens) {
291→      // Skip expired tokens
292→      if (token.expiresAt < new Date()) {
293→        continue;
294→      }
295→      try {
296→        if (await argon2.verify(token.tokenHash, refreshToken)) {
297→          validToken = token;
298→          break;
299→        }
300→      } catch {
301→        // argon2.verify throws on invalid hash format, continue checking
302→        continue;
303→      }
304→    }
305→
306→    if (!validToken) {
307→      throw new UnauthorizedException('Invalid or expired refresh token');
308→    }
309→
310→    // Revoke old token
311→    validToken.revokedAt = new Date();
312→    await this.refreshTokenRepository.save(validToken);
313→
314→    // Create new tokens
315→    const newTokens = await this.tokenService.createTokens(
316→      validToken.userId,
317→      validToken.user.publicKey
318→    );
319→
320→    // Look up user's email from their most recently used auth method
321→    // (covers both email and google auth methods)
322→    const emailMethod = await this.authMethodRepository.findOne({
323→      where: [
324→        { userId: validToken.userId, type: 'email' },
325→        { userId: validToken.userId, type: 'google' },
326→      ],
327→      order: { lastUsedAt: 'DESC' },
328→    });
329→
330→    return {
331→      accessToken: newTokens.accessToken,
332→      refreshToken: newTokens.refreshToken,
333→      // H-09: Fall back to undefined instead of leaking raw identifier hash
334→      email: emailMethod?.identifierDisplay || undefined,
335→    };
336→  }
337→
338→  /**
339→   * Get all linked auth methods for a user.
340→   * Returns identifierDisplay (human-readable) for all method types.
341→   * Falls back to identifier if identifierDisplay is not set.
342→   */
343→  async getLinkedMethods(userId: string): Promise<AuthMethodResponseDto[]> {
344→    const methods = await this.authMethodRepository.find({
345→      where: { userId },
346→      order: { createdAt: 'ASC' },
347→    });
348→
349→    return methods.map((method) => ({
350→      id: method.id,
351→      type: method.type,
352→      // H-09: Fall back to '[redacted]' instead of leaking raw identifier hash
353→      identifier: method.identifierDisplay || '[redacted]',
354→      lastUsedAt: method.lastUsedAt,
355→      createdAt: method.createdAt,
356→    }));
357→  }
358→
359→  /**
360→   * Link a new auth method to an existing user account.
361→   *
362→   * For Google/email: verifies CipherBox-issued JWT to confirm ownership of the new method.
363→   * For wallet: verifies SIWE message+signature to confirm wallet ownership.
364→   *
365→   * Cross-account collision: if the auth method already belongs to a different user,
366→   * a BadRequestException is thrown (user must unlink from the other account first).
367→   */
368→  async linkMethod(userId: string, linkDto: LinkMethodDto): Promise<AuthMethodResponseDto[]> {
369→    // 1. Get the user
370→    const user = await this.userRepository.findOne({ where: { id: userId } });
371→    if (!user) {
372→      throw new UnauthorizedException('User not found');
373→    }
374→
375→    const authMethodType = linkDto.loginType;
376→
377→    if (authMethodType === 'wallet') {
378→      // Wallet linking: verify SIWE message + signature
379→      return this.linkWalletMethod(userId, linkDto);
380→    }
381→
382→    // Google/email linking: verify CipherBox-issued JWT
383→    return this.linkJwtMethod(userId, linkDto);
384→  }
385→
386→  /**
387→   * Link a Google or email auth method via CipherBox JWT verification.
388→   */
389→  private async linkJwtMethod(
390→    userId: string,
391→    linkDto: LinkMethodDto
392→  ): Promise<AuthMethodResponseDto[]> {
393→    // 1. Verify the CipherBox-issued JWT
394→    const payload = await this.verifyCipherBoxJwt(linkDto.idToken);
395→
396→    // 2. Determine type and identifier, hash for lookup
397→    const authMethodType = linkDto.loginType;
398→    const identifier = payload.email || payload.sub;
399→    if (!identifier) {
400→      throw new BadRequestException('Cannot determine identifier from JWT');
401→    }
402→    const identifierHash = this.siweService.hashIdentifier(identifier);
403→
404→    // 3. Check cross-account collision: same identifier linked to a different user
405→    const crossAccountMethod = await this.authMethodRepository.findOne({
406→      where: {
407→        type: authMethodType,
408→        identifierHash,
409→        userId: Not(userId),
410→      },
411→    });
412→
413→    if (crossAccountMethod) {
414→      throw new BadRequestException(
415→        `This ${authMethodType === 'google' ? 'Google account' : 'email'} is already linked to another account`
416→      );
417→    }
418→
419→    // 4. Check if this exact method is already linked to this user
420→    const existingMethod = await this.authMethodRepository.findOne({
421→      where: {
422→        userId,
423→        type: authMethodType,
424→        identifierHash,
425→      },
426→    });
427→
428→    if (existingMethod) {
429→      throw new BadRequestException('This auth method is already linked to your account');
430→    }
431→
432→    // 5. Create new AuthMethod entity with hashed identifier
433→    await this.authMethodRepository.save({
434→      userId,
435→      type: authMethodType,
436→      identifier: identifierHash,
437→      identifierHash,
438→      identifierDisplay: payload.email ? this.siweService.truncateEmail(payload.email) : identifier,
439→      lastUsedAt: new Date(),
440→    });
441→
442→    // 6. Return updated list of methods
443→    return this.getLinkedMethods(userId);
444→  }
445→
446→  /**
447→   * Link a wallet auth method via SIWE verification.
448→   */
449→  private async linkWalletMethod(
450→    userId: string,
451→    linkDto: LinkMethodDto
452→  ): Promise<AuthMethodResponseDto[]> {
453→    // 1. Validate required SIWE fields
454→    if (!linkDto.walletAddress || !linkDto.siweMessage || !linkDto.siweSignature) {
455→      throw new BadRequestException(
456→        'walletAddress, siweMessage, and siweSignature are required for wallet linking'
457→      );
458→    }
459→
460→    // 2. Verify SIWE signature with nonce consumption (C-01: prevent replay)
461→    const parsed = parseSiweMessage(linkDto.siweMessage);
462→    if (!parsed.nonce) {
463→      throw new BadRequestException('Invalid SIWE message: missing nonce');
464→    }
465→
466→    // Consume nonce from Redis (single-use) — same pattern as identity.controller.ts walletLogin
467→    const nonceKey = `siwe:nonce:${parsed.nonce}`;
468→    let nonceDeleted: number;
469→    try {
470→      nonceDeleted = await this.redis.del(nonceKey);
471→    } catch (err) {
472→      this.logger.error('Redis error during nonce consumption', err);
473→      throw new BadRequestException('Nonce verification failed');
474→    }
475→    if (!nonceDeleted) {
476→      throw new BadRequestException('Invalid or expired nonce');
477→    }
478→
479→    const walletAddress = await this.siweService.verifySiweMessage(
480→      linkDto.siweMessage,
481→      linkDto.siweSignature as `0x${string}`,
482→      parsed.nonce
483→    );
484→
485→    // 3. Hash the wallet address for lookup
486→    const addressHash = this.siweService.hashWalletAddress(walletAddress);
487→
488→    // 4. Check cross-account collision: same wallet linked to a different user
489→    const crossAccountMethod = await this.authMethodRepository.findOne({
490→      where: {
491→        type: 'wallet',
492→        identifierHash: addressHash,
493→        userId: Not(userId),
494→      },
495→    });
496→
497→    if (crossAccountMethod) {
498→      throw new BadRequestException('This wallet is already linked to another account');
499→    }
500→
501→    // 5. Check if this wallet is already linked to this user
502→    const existingMethod = await this.authMethodRepository.findOne({
503→      where: {
504→        userId,
505→        type: 'wallet',
506→        identifierHash: addressHash,
507→      },
508→    });
509→
510→    if (existingMethod) {
511→      throw new BadRequestException('This wallet is already linked to your account');
512→    }
513→
514→    // 6. Create wallet auth method with hash + truncated display
515→    const truncated = this.siweService.truncateWalletAddress(walletAddress);
516→    await this.authMethodRepository.save({
517→      userId,
518→      type: 'wallet',
519→      identifier: addressHash,
520→      identifierHash: addressHash,
521→      identifierDisplay: truncated,
522→      lastUsedAt: new Date(),
523→    });
524→
525→    // 7. Return updated list of methods
526→    return this.getLinkedMethods(userId);
527→  }
528→
529→  /**
530→   * Unlink an auth method from a user account.
531→   * Cannot unlink the last remaining auth method.
532→   */
533→  async unlinkMethod(userId: string, methodId: string): Promise<void> {
534→    await this.authMethodRepository.manager.transaction(async (manager) => {
535→      // 1. Lock all auth methods for this user to prevent concurrent unlinks
536→      const methods = await manager
537→        .createQueryBuilder(AuthMethod, 'am')
538→        .setLock('pessimistic_write')
539→        .where('am.userId = :userId', { userId })
540→        .getMany();
541→
542→      // 2. Find the target method
543→      const method = methods.find((m) => m.id === methodId);
544→      if (!method) {
545→        throw new BadRequestException('Auth method not found');
546→      }
547→
548→      // 3. Cannot unlink if only 1 method remains
549→      if (methods.length <= 1) {
550→        throw new BadRequestException('Cannot unlink your last auth method');
551→      }
552→
553→      // 4. Delete the method
554→      await manager.remove(method);
555→    });
556→  }
557→
558→  /**
559→   * Test-only login that bypasses Core Kit entirely.
560→   * Guarded by TEST_LOGIN_SECRET env var — never available in production.
561→   *
562→   * Creates/finds user by email, generates a deterministic secp256k1 keypair,
563→   * and issues tokens. Returns the keypair so E2E tests can initialize vaults.
564→   */
565→  async testLogin(
566→    email: string,
567→    secret: string
568→  ): Promise<{
569→    accessToken: string;
570→    refreshToken: string;
571→    isNewUser: boolean;
572→    publicKeyHex: string;
573→    privateKeyHex: string;
574→  }> {
575→    // 1. Defense-in-depth: never allow in production regardless of env var
576→    const nodeEnv = this.configService.get<string>('NODE_ENV');
577→    if (nodeEnv === 'production') {
578→      throw new ForbiddenException('Test login is not available in production');
579→    }
580→
581→    // 2. Validate TEST_LOGIN_SECRET with timing-safe comparison
582→    const expectedSecret = this.configService.get<string>('TEST_LOGIN_SECRET');
583→    if (!expectedSecret) {
584→      throw new ForbiddenException('Test login is not enabled');
585→    }
586→    const secretBuf = Buffer.from(secret);
587→    const expectedBuf = Buffer.from(expectedSecret);
588→    if (secretBuf.length !== expectedBuf.length || !timingSafeEqual(secretBuf, expectedBuf)) {
589→      throw new UnauthorizedException('Invalid test login secret');
590→    }
591→
592→    // 2. Generate deterministic secp256k1 keypair from email
593→    const { publicKeyHex, privateKeyHex } = this.generateDeterministicKeypair(email);
594→
595→    // 3. Find or create user by email (hash-based lookup)
596→    const normalizedEmail = email.toLowerCase().trim();
597→    const identifierHash = this.siweService.hashIdentifier(normalizedEmail);
598→
599→    const existingMethod = await this.authMethodRepository.findOne({
600→      where: { type: 'email', identifierHash },
601→      relations: ['user'],
602→    });
603→
604→    let user: User;
605→    let isNewUser = false;
606→
607→    if (existingMethod) {
608→      user = existingMethod.user;
609→      // Update publicKey to match deterministic keypair (may differ from Core Kit key)
610→      if (user.publicKey !== publicKeyHex) {
611→        user.publicKey = publicKeyHex;
612→        await this.userRepository.save(user);
613→      }
614→      existingMethod.lastUsedAt = new Date();
615→      await this.authMethodRepository.save(existingMethod);
616→    } else {
617→      isNewUser = true;
618→      user = await this.userRepository.save({ publicKey: publicKeyHex });
619→      await this.authMethodRepository.save({
620→        userId: user.id,
621→        type: 'email',
622→        identifier: identifierHash,
623→        identifierHash,
624→        identifierDisplay: this.siweService.truncateEmail(normalizedEmail),
625→        lastUsedAt: new Date(),
626→      });
627→    }
628→
629→    // 4. Issue tokens
630→    const tokens = await this.tokenService.createTokens(user.id, user.publicKey);
631→
632→    this.logger.log(`Test login: userId=${user.id}, isNew=${isNewUser}`);
633→
634→    return {
635→      accessToken: tokens.accessToken,
636→      refreshToken: tokens.refreshToken,
637→      isNewUser,
638→      publicKeyHex,
639→      privateKeyHex,
640→    };
641→  }
642→
643→  /**
644→   * Generate a deterministic secp256k1 keypair from an email address.
645→   * Same email always produces the same keypair, enabling consistent
646→   * vault encryption across test runs.
647→   */
648→  private generateDeterministicKeypair(email: string): {
649→    publicKeyHex: string;
650→    privateKeyHex: string;
651→  } {
652→    // Derive 32-byte private key from email via SHA-256
653→    const seed = createHash('sha256')
654→      .update(`cipherbox-test-keypair:${email.toLowerCase().trim()}`)
655→      .digest();
656→
657→    // Ensure the seed is a valid secp256k1 private key (must be in [1, n-1])
658→    const n = BigInt('0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141');
659→    let keyInt = BigInt('0x' + seed.toString('hex'));
660→    keyInt = (keyInt % (n - 1n)) + 1n;
661→    const privateKeyHex = keyInt.toString(16).padStart(64, '0');
662→
663→    const ecdh = createECDH('secp256k1');
664→    ecdh.setPrivateKey(Buffer.from(privateKeyHex, 'hex'));
665→    const publicKeyHex = ecdh.getPublicKey().toString('hex'); // 65 bytes uncompressed
666→
667→    return { publicKeyHex, privateKeyHex };
668→  }
669→}
