  1→import { Injectable, Logger } from '@nestjs/common';
  2→import { InjectRepository } from '@nestjs/typeorm';
  3→import { Repository, In, LessThanOrEqual } from 'typeorm';
  4→import { ConfigService } from '@nestjs/config';
  5→import { IpnsRepublishSchedule } from './republish-schedule.entity';
  6→import { FolderIpns } from '../ipns/entities/folder-ipns.entity';
  7→import { TeeService, RepublishEntry, RepublishResult } from '../tee/tee.service';
  8→import { TeeKeyStateService } from '../tee/tee-key-state.service';
  9→
 10→/** Max entries per TEE request -- increased for per-file IPNS scalability (file records are smaller payloads) */
 11→const BATCH_SIZE = 100;
 12→
 13→/** After this many consecutive failures, mark entry as 'stale' */
 14→const MAX_CONSECUTIVE_FAILURES = 10;
 15→
 16→/** Republish interval in hours */
 17→const REPUBLISH_INTERVAL_HOURS = 6;
 18→
 19→/** Max backoff cap in seconds */
 20→const MAX_BACKOFF_SECONDS = 3600;
 21→
 22→/** Base backoff in seconds */
 23→const BASE_BACKOFF_SECONDS = 30;
 24→
 25→@Injectable()
 26→export class RepublishService {
 27→  private readonly logger = new Logger(RepublishService.name);
 28→  private readonly delegatedRoutingUrl: string;
 29→  private readonly maxPublishRetries = 3;
 30→  private readonly publishBaseDelayMs = 1000;
 31→
 32→  constructor(
 33→    @InjectRepository(IpnsRepublishSchedule)
 34→    private readonly scheduleRepository: Repository<IpnsRepublishSchedule>,
 35→    @InjectRepository(FolderIpns)
 36→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 37→    private readonly teeService: TeeService,
 38→    private readonly teeKeyStateService: TeeKeyStateService,
 39→    private readonly configService: ConfigService
 40→  ) {
 41→    this.delegatedRoutingUrl = this.configService.get<string>(
 42→      'DELEGATED_ROUTING_URL',
 43→      'https://delegated-ipfs.dev'
 44→    );
 45→  }
 46→
 47→  /**
 48→   * Query entries that are due for republishing.
 49→   * Returns entries where status is 'active' or 'retrying' and next_republish_at <= now.
 50→   */
 51→  async getDueEntries(): Promise<IpnsRepublishSchedule[]> {
 52→    return this.scheduleRepository.find({
 53→      where: {
 54→        status: In(['active', 'retrying']),
 55→        nextRepublishAt: LessThanOrEqual(new Date()),
 56→      },
 57→      order: { nextRepublishAt: 'ASC' },
 58→      take: 2000,
 59→    });
 60→  }
 61→
 62→  /**
 63→   * Main orchestration: process all due republish entries.
 64→   * Batches entries, sends to TEE for signing, publishes signed records.
 65→   */
 66→  async processRepublishBatch(): Promise<{
 67→    processed: number;
 68→    succeeded: number;
 69→    failed: number;
 70→  }> {
 71→    const dueEntries = await this.getDueEntries();
 72→
 73→    if (dueEntries.length === 0) {
 74→      this.logger.debug('No entries due for republishing');
 75→      return { processed: 0, succeeded: 0, failed: 0 };
 76→    }
 77→
 78→    this.logger.log(`Processing ${dueEntries.length} due republish entries`);
 79→
 80→    // Soft capacity warning for large vaults with many per-file IPNS records
 81→    if (dueEntries.length > 1000) {
 82→      this.logger.warn(
 83→        `High IPNS record count: ${dueEntries.length} entries due for republishing - approaching capacity limits`
 84→      );
 85→    }
 86→
 87→    // Fetch current TEE epoch state for the batch
 88→    const teeState = await this.teeKeyStateService.getCurrentState();
 89→    if (!teeState) {
 90→      this.logger.error('TEE key state not initialized, cannot process republish batch');
 91→      return { processed: dueEntries.length, succeeded: 0, failed: dueEntries.length };
 92→    }
 93→
 94→    const currentEpoch = teeState.currentEpoch;
 95→    const previousEpoch = teeState.previousEpoch;
 96→
 97→    let totalSucceeded = 0;
 98→    let totalFailed = 0;
 99→
100→    // Split into batches of BATCH_SIZE
101→    for (let i = 0; i < dueEntries.length; i += BATCH_SIZE) {
102→      const batch = dueEntries.slice(i, i + BATCH_SIZE);
103→
104→      // Build RepublishEntry payloads for TEE
105→      const teeEntries: RepublishEntry[] = batch.map((entry) => ({
106→        encryptedIpnsKey: entry.encryptedIpnsKey.toString('base64'),
107→        keyEpoch: entry.keyEpoch,
108→        ipnsName: entry.ipnsName,
109→        latestCid: entry.latestCid,
110→        sequenceNumber: entry.sequenceNumber,
111→        currentEpoch,
112→        previousEpoch,
113→      }));
114→
115→      let teeResults: RepublishResult[];
116→      try {
117→        teeResults = await this.teeService.republish(teeEntries);
118→      } catch (error) {
119→        // TEE unreachable -- mark entire batch as failed
120→        const message = error instanceof Error ? error.message : String(error);
121→        this.logger.error(`TEE worker unreachable: ${message}`);
122→
123→        for (const entry of batch) {
124→          await this.handleEntryFailure(entry, `TEE unreachable: ${message}`);
125→        }
126→        totalFailed += batch.length;
127→        continue;
128→      }
129→
130→      // Process results
131→      for (let j = 0; j < batch.length; j++) {
132→        const entry = batch[j];
133→        const result = teeResults[j];
134→
135→        if (!result) {
136→          await this.handleEntryFailure(entry, 'No result from TEE worker');
137→          totalFailed++;
138→          continue;
139→        }
140→
141→        if (result.success && result.signedRecord && result.newSequenceNumber) {
142→          // TEE signing succeeded -- now publish to delegated routing
143→          try {
144→            await this.publishSignedRecord(entry.ipnsName, result.signedRecord);
145→
146→            // Update schedule entry on success
147→            entry.sequenceNumber = result.newSequenceNumber;
148→            entry.lastRepublishAt = new Date();
149→            entry.consecutiveFailures = 0;
150→            entry.status = 'active';
151→            entry.lastError = null;
152→            entry.nextRepublishAt = this.nextRepublishTime();
153→
154→            // Handle epoch upgrade if TEE re-encrypted with current epoch
155→            if (result.upgradedEncryptedKey && result.upgradedKeyEpoch !== undefined) {
156→              entry.encryptedIpnsKey = Buffer.from(result.upgradedEncryptedKey, 'base64');
157→              entry.keyEpoch = result.upgradedKeyEpoch;
158→              this.logger.log(
159→                `Epoch upgrade for ${entry.ipnsName}: epoch ${entry.keyEpoch} -> ${result.upgradedKeyEpoch}`
160→              );
161→            }
162→
163→            await this.scheduleRepository.save(entry);
164→
165→            // Keep FolderIpns sequence number in sync
166→            await this.syncFolderIpnsSequence(
167→              entry.userId,
168→              entry.ipnsName,
169→              result.newSequenceNumber
170→            );
171→
172→            totalSucceeded++;
173→          } catch (publishError) {
174→            // TEE signing succeeded but publishing failed (RESEARCH.md pitfall 6)
175→            const message =
176→              publishError instanceof Error ? publishError.message : String(publishError);
177→            this.logger.warn(
178→              `Signing succeeded but publish failed for ${entry.ipnsName}: ${message}`
179→            );
180→            await this.handleEntryFailure(
181→              entry,
182→              `Publish failed after successful signing: ${message}`
183→            );
184→            totalFailed++;
185→          }
186→        } else {
187→          // TEE signing failed
188→          await this.handleEntryFailure(entry, result.error || 'Unknown TEE error');
189→          totalFailed++;
190→        }
191→      }
192→    }
193→
194→    this.logger.log(
195→      `Republish batch complete: processed=${dueEntries.length}, succeeded=${totalSucceeded}, failed=${totalFailed}`
196→    );
197→
198→    return {
199→      processed: dueEntries.length,
200→      succeeded: totalSucceeded,
201→      failed: totalFailed,
202→    };
203→  }
204→
205→  /**
206→   * Publish a signed IPNS record to delegated routing with retries.
207→   */
208→  async publishSignedRecord(ipnsName: string, signedRecordBase64: string): Promise<void> {
209→    const url = `${this.delegatedRoutingUrl}/routing/v1/ipns/${ipnsName}`;
210→    const recordBytes = Uint8Array.from(atob(signedRecordBase64), (c) => c.charCodeAt(0));
211→
212→    let lastError: Error | null = null;
213→
214→    for (let attempt = 0; attempt < this.maxPublishRetries; attempt++) {
215→      try {
216→        const response = await fetch(url, {
217→          method: 'PUT',
218→          headers: {
219→            'Content-Type': 'application/vnd.ipfs.ipns-record',
220→          },
221→          body: recordBytes as unknown as BodyInit,
222→        });
223→
224→        if (response.ok) {
225→          this.logger.debug(`Signed IPNS record published for ${ipnsName}`);
226→          return;
227→        }
228→
229→        if (response.status === 429) {
230→          const retryAfter = response.headers.get('Retry-After');
231→          const delayMs = retryAfter
232→            ? parseInt(retryAfter, 10) * 1000
233→            : this.publishBaseDelayMs * Math.pow(2, attempt);
234→          this.logger.warn(`Rate limited on republish for ${ipnsName}, retrying in ${delayMs}ms`);
235→          await this.delay(delayMs);
236→          continue;
237→        }
238→
239→        throw new Error(`Delegated routing returned ${response.status}`);
240→      } catch (error) {
241→        lastError = error instanceof Error ? error : new Error(String(error));
242→
243→        if (attempt < this.maxPublishRetries - 1) {
244→          const delayMs = this.publishBaseDelayMs * Math.pow(2, attempt);
245→          this.logger.warn(
246→            `Republish attempt ${attempt + 1} failed for ${ipnsName}, retrying in ${delayMs}ms`
247→          );
248→          await this.delay(delayMs);
249→        }
250→      }
251→    }
252→
253→    throw lastError || new Error('Publish failed after retries');
254→  }
255→
256→  /**
257→   * Enroll or update a folder for TEE republishing.
258→   * Called when a folder is published with TEE-encrypted IPNS key.
259→   */
260→  async enrollFolder(
261→    userId: string,
262→    ipnsName: string,
263→    encryptedIpnsKey: Buffer,
264→    keyEpoch: number,
265→    latestCid: string,
266→    sequenceNumber: string
267→  ): Promise<void> {
268→    const existing = await this.scheduleRepository.findOne({
269→      where: { userId, ipnsName },
270→    });
271→
272→    if (existing) {
273→      // Update existing enrollment
274→      existing.encryptedIpnsKey = encryptedIpnsKey;
275→      existing.keyEpoch = keyEpoch;
276→      existing.latestCid = latestCid;
277→      existing.sequenceNumber = sequenceNumber;
278→      existing.nextRepublishAt = this.nextRepublishTime();
279→      await this.scheduleRepository.save(existing);
280→      this.logger.log(`Updated republish enrollment for ${ipnsName}`);
281→    } else {
282→      // Create new enrollment
283→      const schedule = this.scheduleRepository.create({
284→        userId,
285→        ipnsName,
286→        encryptedIpnsKey,
287→        keyEpoch,
288→        latestCid,
289→        sequenceNumber,
290→        nextRepublishAt: this.nextRepublishTime(),
291→        status: 'active',
292→        consecutiveFailures: 0,
293→        lastError: null,
294→        lastRepublishAt: null,
295→      });
296→      await this.scheduleRepository.save(schedule);
297→      this.logger.log(`Enrolled ${ipnsName} for TEE republishing (epoch ${keyEpoch})`);
298→    }
299→  }
300→
301→  /**
302→   * Unenroll an IPNS record from TEE republishing.
303→   * Called when files are deleted to prevent orphaned TEE enrollments.
304→   */
305→  async unenrollIpns(userId: string, ipnsName: string): Promise<void> {
306→    const result = await this.scheduleRepository.delete({ userId, ipnsName });
307→    if (result.affected && result.affected > 0) {
308→      this.logger.log(`Unenrolled ${ipnsName} from TEE republishing for user ${userId}`);
309→    } else {
310→      this.logger.debug(
311→        `No republish enrollment found for ${ipnsName} (user ${userId}) - nothing to unenroll`
312→      );
313→    }
314→  }
315→
316→  /**
317→   * Get aggregate health stats for admin endpoint.
318→   */
319→  async getHealthStats(): Promise<{
320→    pending: number;
321→    failed: number;
322→    stale: number;
323→    lastRunAt: Date | null;
324→    currentEpoch: number | null;
325→    teeHealthy: boolean;
326→  }> {
327→    const [pending, failed, stale] = await Promise.all([
328→      this.scheduleRepository.count({ where: { status: 'active' } }),
329→      this.scheduleRepository.count({ where: { status: 'retrying' } }),
330→      this.scheduleRepository.count({ where: { status: 'stale' } }),
331→    ]);
332→
333→    // Get most recent successful republish
334→    const lastRun = await this.scheduleRepository.findOne({
335→      where: { status: 'active' },
336→      order: { lastRepublishAt: 'DESC' },
337→    });
338→
339→    // Get current TEE epoch
340→    const teeState = await this.teeKeyStateService.getCurrentState();
341→
342→    // Check TEE worker health
343→    let teeHealthy = false;
344→    try {
345→      const health = await this.teeService.getHealth();
346→      teeHealthy = health.healthy;
347→    } catch {
348→      teeHealthy = false;
349→    }
350→
351→    return {
352→      pending,
353→      failed,
354→      stale,
355→      lastRunAt: lastRun?.lastRepublishAt ?? null,
356→      currentEpoch: teeState?.currentEpoch ?? null,
357→      teeHealthy,
358→    };
359→  }
360→
361→  /**
362→   * Reactivate all stale entries (e.g., when TEE recovers).
363→   * Resets status to 'active' with immediate next republish time.
364→   */
365→  async reactivateStaleEntries(): Promise<number> {
366→    const result = await this.scheduleRepository.update(
367→      { status: 'stale' },
368→      {
369→        status: 'active',
370→        consecutiveFailures: 0,
371→        nextRepublishAt: new Date(),
372→        lastError: null,
373→      }
374→    );
375→
376→    const count = result.affected ?? 0;
377→    if (count > 0) {
378→      this.logger.log(`Reactivated ${count} stale entries after TEE recovery`);
379→    }
380→    return count;
381→  }
382→
383→  /**
384→   * Handle a failed entry: increment failures, apply backoff or mark stale.
385→   */
386→  private async handleEntryFailure(
387→    entry: IpnsRepublishSchedule,
388→    errorMessage: string
389→  ): Promise<void> {
390→    entry.consecutiveFailures += 1;
391→    // NEVER log key material -- only ipnsName, epoch, and failure count
392→    entry.lastError = errorMessage.substring(0, 500);
393→
394→    if (entry.consecutiveFailures >= MAX_CONSECUTIVE_FAILURES) {
395→      entry.status = 'stale';
396→      entry.nextRepublishAt = new Date(Date.now() + 365 * 24 * 60 * 60 * 1000); // Far future
397→      this.logger.warn(
398→        `Entry ${entry.ipnsName} marked stale after ${entry.consecutiveFailures} failures`
399→      );
400→    } else {
401→      entry.status = 'retrying';
402→      const backoffSeconds = Math.min(
403→        BASE_BACKOFF_SECONDS * Math.pow(2, entry.consecutiveFailures),
404→        MAX_BACKOFF_SECONDS
405→      );
406→      entry.nextRepublishAt = new Date(Date.now() + backoffSeconds * 1000);
407→      this.logger.warn(
408→        `Entry ${entry.ipnsName} failed (${entry.consecutiveFailures}/${MAX_CONSECUTIVE_FAILURES}), retrying in ${backoffSeconds}s`
409→      );
410→    }
411→
412→    await this.scheduleRepository.save(entry);
413→  }
414→
415→  /**
416→   * Sync the FolderIpns sequence number after successful republish.
417→   * Handles both folder and per-file IPNS records (keyed by userId + ipnsName).
418→   */
419→  private async syncFolderIpnsSequence(
420→    userId: string,
421→    ipnsName: string,
422→    newSequenceNumber: string
423→  ): Promise<void> {
424→    try {
425→      await this.folderIpnsRepository.update(
426→        { userId, ipnsName },
427→        { sequenceNumber: newSequenceNumber }
428→      );
429→    } catch (error) {
430→      // Non-fatal: log and continue
431→      const message = error instanceof Error ? error.message : String(error);
432→      this.logger.warn(`Failed to sync FolderIpns sequence for ${ipnsName}: ${message}`);
433→    }
434→  }
435→
436→  /**
437→   * Calculate next republish time (now + 6 hours).
438→   */
439→  private nextRepublishTime(): Date {
440→    return new Date(Date.now() + REPUBLISH_INTERVAL_HOURS * 60 * 60 * 1000);
441→  }
442→
443→  private delay(ms: number): Promise<void> {
444→    return new Promise((resolve) => setTimeout(resolve, ms));
445→  }
446→}
447→

  1→/**
  2→ * useSharedNavigation -- Navigation hook for browsing shared content.
  3→ *
  4→ * Similar to useFolderNavigation but with a different key source:
  5→ * - Top level: shares received via share records
  6→ * - Folder browsing: re-wrapped keys from share_keys table
  7→ * - File download: re-wrapped fileKey from share_keys table
  8→ *
  9→ * Security: All keys are ECIES-wrapped for the current user.
 10→ * The server never sees plaintext keys.
 11→ */
 12→
 13→import { useState, useCallback, useEffect, useRef } from 'react';
 14→import {
 15→  unwrapKey,
 16→  hexToBytes,
 17→  decryptFolderMetadata,
 18→  decryptFileMetadata,
 19→  type FolderChild,
 20→  type FolderEntry,
 21→  type FilePointer,
 22→  type EncryptedFolderMetadata,
 23→  type EncryptedFileMetadata,
 24→} from '@cipherbox/crypto';
 25→import { useAuthStore } from '../stores/auth.store';
 26→import { useShareStore, type ReceivedShare } from '../stores/share.store';
 27→import { fetchReceivedShares, fetchShareKeys, hideShare } from '../services/share.service';
 28→import { resolveIpnsRecord } from '../services/ipns.service';
 29→import { fetchFromIpfs } from '../lib/api/ipfs';
 30→import { downloadFile, triggerBrowserDownload } from '../services/download.service';
 31→import { useDownloadStore } from '../stores/download.store';
 32→
 33→/**
 34→ * Breadcrumb entry for shared navigation.
 35→ */
 36→export type SharedBreadcrumb = {
 37→  id: string;
 38→  name: string;
 39→};
 40→
 41→/**
 42→ * A shared item displayed in the top-level shared list.
 43→ * Extends the original FolderChild with sharing metadata.
 44→ */
 45→export type SharedListItem = {
 46→  share: ReceivedShare;
 47→  /** Resolved folder children (for folders), or null (for files / unresolved) */
 48→  children: FolderChild[] | null;
 49→  /** Folder key for this shared item (decrypted from share record) */
 50→  folderKey: Uint8Array | null;
 51→};
 52→
 53→type SharedView = 'list' | 'folder';
 54→
 55→type UseSharedNavigationReturn = {
 56→  currentView: SharedView;
 57→  currentShareId: string | null;
 58→  sharedItems: SharedListItem[];
 59→  folderChildren: FolderChild[];
 60→  folderKey: Uint8Array | null;
 61→  breadcrumbs: SharedBreadcrumb[];
 62→  isLoading: boolean;
 63→  error: string | null;
 64→  navigateToShare: (shareId: string) => Promise<void>;
 65→  navigateToSubfolder: (folderId: string, folderName: string) => Promise<void>;
 66→  navigateUp: () => void;
 67→  navigateToRoot: () => void;
 68→  navigateToBreadcrumb: (crumbIndex: number) => void;
 69→  downloadSharedFile: (item: FilePointer) => Promise<void>;
 70→  hideSharedItem: (shareId: string) => Promise<void>;
 71→};
 72→
 73→/**
 74→ * Hook for browsing shared content.
 75→ *
 76→ * Manages the "Shared with me" browsing experience.
 77→ * Top-level view shows received shares as a flat list.
 78→ * Clicking a shared folder navigates into it using re-wrapped keys.
 79→ */
 80→export function useSharedNavigation(): UseSharedNavigationReturn {
 81→  const [currentView, setCurrentView] = useState<SharedView>('list');
 82→  const [currentShareId, setCurrentShareId] = useState<string | null>(null);
 83→  const [sharedItems, setSharedItems] = useState<SharedListItem[]>([]);
 84→  const [folderChildren, setFolderChildren] = useState<FolderChild[]>([]);
 85→  const [folderKey, setFolderKey] = useState<Uint8Array | null>(null);
 86→  const [breadcrumbs, setBreadcrumbs] = useState<SharedBreadcrumb[]>([]);
 87→  const [isLoading, setIsLoading] = useState(true);
 88→  const [error, setError] = useState<string | null>(null);
 89→
 90→  // Navigation stack for folder browsing within a share
 91→  const navStackRef = useRef<
 92→    Array<{
 93→      folderId: string;
 94→      folderName: string;
 95→      children: FolderChild[];
 96→      folderKey: Uint8Array;
 97→    }>
 98→  >([]);
 99→
100→  // Cache share keys per shareId with TTL to avoid refetching
101→  const shareKeysCache = useRef<
102→    Map<
103→      string,
104→      {
105→        keys: Array<{ keyType: 'file' | 'folder'; itemId: string; encryptedKey: string }>;
106→        fetchedAt: number;
107→      }
108→    >
109→  >(new Map());
110→
111→  /**
112→   * Load received shares on mount.
113→   */
114→  useEffect(() => {
115→    let cancelled = false;
116→
117→    async function loadShares() {
118→      setIsLoading(true);
119→      setError(null);
120→
121→      try {
122→        const shares = await fetchReceivedShares();
123→        if (cancelled) return;
124→
125→        useShareStore.getState().setReceivedShares(shares);
126→
127→        const items: SharedListItem[] = shares.map((share) => ({
128→          share,
129→          children: null,
130→          folderKey: null,
131→        }));
132→
133→        setSharedItems(items);
134→      } catch (err) {
135→        if (cancelled) return;
136→        console.error('Failed to load shared items:', err);
137→        setError('Failed to load shared items');
138→      } finally {
139→        if (!cancelled) {
140→          setIsLoading(false);
141→        }
142→      }
143→    }
144→
145→    loadShares();
146→    return () => {
147→      cancelled = true;
148→      // Zero all decrypted folder keys on unmount
149→      setFolderKey((prev) => {
150→        if (prev) prev.fill(0);
151→        return null;
152→      });
153→      for (const entry of navStackRef.current) {
154→        entry.folderKey.fill(0);
155→      }
156→      navStackRef.current = [];
157→    };
158→  }, []);
159→
160→  /** Cache TTL for share keys (60 seconds). */
161→  const SHARE_KEYS_CACHE_TTL = 60_000;
162→
163→  /**
164→   * Get share keys for a share, with TTL-based caching.
165→   */
166→  const getShareKeys = useCallback(async (shareId: string) => {
167→    const cached = shareKeysCache.current.get(shareId);
168→    if (cached && Date.now() - cached.fetchedAt < SHARE_KEYS_CACHE_TTL) {
169→      return cached.keys;
170→    }
171→
172→    const keys = await fetchShareKeys(shareId);
173→    shareKeysCache.current.set(shareId, { keys, fetchedAt: Date.now() });
174→    return keys;
175→  }, []);
176→
177→  /**
178→   * Navigate into a shared folder from the top-level list.
179→   */
180→  const navigateToShare = useCallback(
181→    async (shareId: string) => {
182→      const auth = useAuthStore.getState();
183→      if (!auth.vaultKeypair) {
184→        setError('No keypair available');
185→        return;
186→      }
187→
188→      const shareItem = sharedItems.find((s) => s.share.shareId === shareId);
189→      if (!shareItem) return;
190→
191→      const share = shareItem.share;
192→
193→      setIsLoading(true);
194→      setError(null);
195→
196→      try {
197→        // Unwrap the shared item's key with our private key
198→        const itemKey = await unwrapKey(
199→          hexToBytes(share.encryptedKey),
200→          auth.vaultKeypair.privateKey
201→        );
202→
203→        if (share.itemType === 'folder') {
204→          let folderKeyStored = false;
205→          try {
206→            // Resolve folder IPNS to get metadata
207→            const resolved = await resolveIpnsRecord(share.ipnsName);
208→            if (!resolved) {
209→              throw new Error('Could not resolve shared folder IPNS');
210→            }
211→
212→            // Fetch and decrypt folder metadata
213→            const encryptedBytes = await fetchFromIpfs(resolved.cid);
214→            const encryptedJson = new TextDecoder().decode(encryptedBytes);
215→            const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
216→            const metadata = await decryptFolderMetadata(encrypted, itemKey);
217→
218→            // Set folder state
219→            setCurrentView('folder');
220→            setCurrentShareId(shareId);
221→            setFolderChildren(metadata.children ?? []);
222→            setFolderKey(itemKey);
223→            folderKeyStored = true;
224→            setBreadcrumbs([{ id: shareId, name: share.itemName }]);
225→            navStackRef.current = [];
226→          } finally {
227→            if (!folderKeyStored) itemKey.fill(0);
228→          }
229→        } else {
230→          // For files, trigger download directly
231→          // itemKey is the parent folder key; downloadSharedFileFromShare unwraps its own copy
232→          itemKey.fill(0);
233→          await downloadSharedFileFromShare(share, auth.vaultKeypair.privateKey);
234→        }
235→      } catch (err) {
236→        console.error('Failed to navigate to shared item:', err);
237→        setError('Failed to open shared item');
238→      } finally {
239→        setIsLoading(false);
240→      }
241→    },
242→    [sharedItems]
243→  );
244→
245→  /**
246→   * Navigate into a subfolder within a shared folder.
247→   */
248→  const navigateToSubfolder = useCallback(
249→    async (folderId: string, folderName: string) => {
250→      const auth = useAuthStore.getState();
251→      if (!auth.vaultKeypair || !currentShareId) return;
252→
253→      setIsLoading(true);
254→      setError(null);
255→
256→      try {
257→        // Get re-wrapped keys for this share
258→        const keys = await getShareKeys(currentShareId);
259→
260→        // Find the re-wrapped folder key for this subfolder
261→        const keyRecord = keys.find((k) => k.keyType === 'folder' && k.itemId === folderId);
262→        if (!keyRecord) {
263→          throw new Error('No key available for this subfolder');
264→        }
265→
266→        // Unwrap the subfolder key
267→        const subfolderKey = await unwrapKey(
268→          hexToBytes(keyRecord.encryptedKey),
269→          auth.vaultKeypair.privateKey
270→        );
271→        let subfolderKeyStored = false;
272→
273→        try {
274→          // Find the subfolder entry to get its IPNS name
275→          const folderEntry = folderChildren.find(
276→            (c): c is FolderEntry => c.type === 'folder' && c.id === folderId
277→          );
278→          if (!folderEntry) {
279→            throw new Error('Subfolder not found in current children');
280→          }
281→
282→          // Resolve subfolder IPNS
283→          const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
284→          if (!resolved) {
285→            throw new Error('Could not resolve subfolder IPNS');
286→          }
287→
288→          // Fetch and decrypt subfolder metadata
289→          const encryptedBytes = await fetchFromIpfs(resolved.cid);
290→          const encryptedJson = new TextDecoder().decode(encryptedBytes);
291→          const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
292→          const metadata = await decryptFolderMetadata(encrypted, subfolderKey);
293→
294→          // Push current state to nav stack
295→          if (folderKey) {
296→            navStackRef.current.push({
297→              folderId: breadcrumbs[breadcrumbs.length - 1]?.id ?? '',
298→              folderName: breadcrumbs[breadcrumbs.length - 1]?.name ?? '',
299→              children: folderChildren,
300→              folderKey,
301→            });
302→          }
303→
304→          // Update state
305→          setFolderChildren(metadata.children ?? []);
306→          setFolderKey(subfolderKey);
307→          subfolderKeyStored = true;
308→          setBreadcrumbs((prev) => [...prev, { id: folderId, name: folderName }]);
309→        } finally {
310→          if (!subfolderKeyStored) subfolderKey.fill(0);
311→        }
312→      } catch (err) {
313→        console.error('Failed to navigate to subfolder:', err);
314→        setError('Failed to open subfolder');
315→      } finally {
316→        setIsLoading(false);
317→      }
318→    },
319→    [currentShareId, folderChildren, folderKey, breadcrumbs, getShareKeys]
320→  );
321→
322→  /**
323→   * Navigate back to the top-level shared list.
324→   * Zeroes all decrypted folder keys from memory before clearing state.
325→   */
326→  const navigateToRoot = useCallback(() => {
327→    // Zero current folder key
328→    if (folderKey) folderKey.fill(0);
329→    // Zero all nav stack folder keys
330→    for (const entry of navStackRef.current) {
331→      entry.folderKey.fill(0);
332→    }
333→    setCurrentView('list');
334→    setCurrentShareId(null);
335→    setFolderChildren([]);
336→    setFolderKey(null);
337→    setBreadcrumbs([]);
338→    navStackRef.current = [];
339→    setError(null);
340→  }, [folderKey]);
341→
342→  /**
343→   * Navigate up one level.
344→   */
345→  const navigateUp = useCallback(() => {
346→    if (navStackRef.current.length > 0) {
347→      // Zero current folder key before replacing
348→      if (folderKey) folderKey.fill(0);
349→      // Pop from nav stack
350→      const prev = navStackRef.current.pop()!;
351→      setFolderChildren(prev.children);
352→      setFolderKey(prev.folderKey);
353→      setBreadcrumbs((crumbs) => crumbs.slice(0, -1));
354→    } else if (currentView === 'folder') {
355→      // Back to top-level list
356→      navigateToRoot();
357→    }
358→  }, [currentView, folderKey, navigateToRoot]);
359→
360→  /**
361→   * Navigate directly to a breadcrumb level, zeroing all intermediate keys.
362→   * More efficient than calling navigateUp() in a loop.
363→   */
364→  const navigateToBreadcrumb = useCallback(
365→    (crumbIndex: number) => {
366→      const popsNeeded = breadcrumbs.length - 1 - crumbIndex;
367→      if (popsNeeded <= 0) return;
368→      // Zero the current folder key
369→      if (folderKey) folderKey.fill(0);
370→      // Zero and discard all intermediate keys
371→      for (let i = 0; i < popsNeeded - 1; i++) {
372→        const entry = navStackRef.current.pop();
373→        if (entry) entry.folderKey.fill(0);
374→      }
375→      // Restore the target level
376→      const target = navStackRef.current.pop();
377→      if (target) {
378→        setFolderChildren(target.children);
379→        setFolderKey(target.folderKey);
380→        setBreadcrumbs((crumbs) => crumbs.slice(0, crumbIndex + 1));
381→      }
382→    },
383→    [breadcrumbs, folderKey]
384→  );
385→
386→  /**
387→   * Download a shared file from the top-level list.
388→   * The share's encryptedKey wraps the parent folder key (needed to decrypt file metadata).
389→   * The actual file key is stored as a child key in share_keys.
390→   */
391→  async function downloadSharedFileFromShare(
392→    share: ReceivedShare,
393→    privateKey: Uint8Array
394→  ): Promise<void> {
395→    if (share.itemType !== 'file') return;
396→
397→    const downloadStore = useDownloadStore.getState();
398→
399→    try {
400→      downloadStore.startDownload(share.itemName);
401→
402→      // Unwrap the parent folder key from the share record
403→      const parentFolderKey = await unwrapKey(hexToBytes(share.encryptedKey), privateKey);
404→
405→      let fileMeta: Awaited<ReturnType<typeof decryptFileMetadata>>;
406→      try {
407→        // Resolve file IPNS metadata and decrypt with parent folder key
408→        const resolved = await resolveIpnsRecord(share.ipnsName);
409→        if (!resolved) {
410→          throw new Error('File metadata IPNS not found');
411→        }
412→
413→        const encryptedBytes = await fetchFromIpfs(resolved.cid);
414→        const encryptedJson = new TextDecoder().decode(encryptedBytes);
415→        const encrypted: EncryptedFileMetadata = JSON.parse(encryptedJson);
416→        fileMeta = await decryptFileMetadata(encrypted, parentFolderKey);
417→      } finally {
418→        parentFolderKey.fill(0);
419→      }
420→
421→      // Get the re-wrapped file key from share_keys
422→      const keys = await fetchShareKeys(share.shareId);
423→      const fileKeyRecord = keys.find((k) => k.keyType === 'file');
424→      if (!fileKeyRecord) {
425→        throw new Error('No re-wrapped file key available for this file');
426→      }
427→
428→      // Download and decrypt using the re-wrapped file key
429→      const plaintext = await downloadFile(
430→        {
431→          cid: fileMeta.cid,
432→          iv: fileMeta.fileIv,
433→          wrappedKey: fileKeyRecord.encryptedKey,
434→          originalName: share.itemName,
435→          encryptionMode: fileMeta.encryptionMode,
436→        },
437→        privateKey
438→      );
439→
440→      downloadStore.setDecrypting();
441→      triggerBrowserDownload(plaintext, share.itemName);
442→      downloadStore.setSuccess();
443→    } catch (err) {
444→      const message = (err as Error).message || 'Download failed';
445→      downloadStore.setError(message);
446→      console.error('Shared file download failed:', err);
447→    }
448→  }
449→
450→  /**
451→   * Download a shared file from within a shared folder.
452→   * Uses re-wrapped file keys from share_keys.
453→   */
454→  const downloadSharedFile = useCallback(
455→    async (item: FilePointer) => {
456→      const auth = useAuthStore.getState();
457→      if (!auth.vaultKeypair || !currentShareId || !folderKey) return;
458→
459→      const downloadStore = useDownloadStore.getState();
460→
461→      try {
462→        downloadStore.startDownload(item.name);
463→
464→        // Get share keys for file key lookup
465→        const keys = await getShareKeys(currentShareId);
466→
467→        // First resolve the file metadata using the parent folder key
468→        const resolved = await resolveIpnsRecord(item.fileMetaIpnsName);
469→        if (!resolved) {
470→          throw new Error('File metadata IPNS not found');
471→        }
472→
473→        const encryptedBytes = await fetchFromIpfs(resolved.cid);
474→        const encryptedJson = new TextDecoder().decode(encryptedBytes);
475→        const encrypted: EncryptedFileMetadata = JSON.parse(encryptedJson);
476→        const fileMeta = await decryptFileMetadata(encrypted, folderKey);
477→
478→        // Look for a re-wrapped file key in share_keys
479→        const fileKeyRecord = keys.find((k) => k.keyType === 'file' && k.itemId === item.id);
480→
481→        if (!fileKeyRecord) {
482→          throw new Error('No re-wrapped file key available for this file');
483→        }
484→
485→        // Use re-wrapped file key from share_keys
486→        // downloadFile handles unwrapping internally via wrappedKey + privateKey
487→        const plaintext = await downloadFile(
488→          {
489→            cid: fileMeta.cid,
490→            iv: fileMeta.fileIv,
491→            wrappedKey: fileKeyRecord.encryptedKey,
492→            originalName: item.name,
493→            encryptionMode: fileMeta.encryptionMode,
494→          },
495→          auth.vaultKeypair.privateKey
496→        );
497→
498→        downloadStore.setDecrypting();
499→        triggerBrowserDownload(plaintext, item.name);
500→        downloadStore.setSuccess();
501→      } catch (err) {
502→        const message = (err as Error).message || 'Download failed';
503→        downloadStore.setError(message);
504→        console.error('Shared file download failed:', err);
505→      }
506→    },
507→    [currentShareId, folderKey, getShareKeys]
508→  );
509→
510→  /**
511→   * Hide a shared item from the user's view.
512→   */
513→  const hideSharedItem = useCallback(async (shareId: string) => {
514→    try {
515→      await hideShare(shareId);
516→      useShareStore.getState().removeReceivedShare(shareId);
517→      setSharedItems((prev) => prev.filter((s) => s.share.shareId !== shareId));
518→    } catch (err) {
519→      console.error('Failed to hide share:', err);
520→      setError('Failed to hide shared item');
521→    }
522→  }, []);
523→
524→  return {
525→    currentView,
526→    currentShareId,
527→    sharedItems,
528→    folderChildren,
529→    folderKey,
530→    breadcrumbs,
531→    isLoading,
532→    error,
533→    navigateToShare,
534→    navigateToSubfolder,
535→    navigateUp,
536→    navigateToRoot,
537→    navigateToBreadcrumb,
538→    downloadSharedFile,
539→    hideSharedItem,
540→  };
541→}
