 51→    private authMethodRepository: Repository<AuthMethod>
 52→  ) {
 53→    this.redis = new Redis({
 54→      host: this.configService.get('REDIS_HOST', 'localhost'),
 55→      port: this.configService.get<number>('REDIS_PORT', 6379),
 56→      password: this.configService.get('REDIS_PASSWORD', undefined),
 57→      lazyConnect: true,
 58→    });
 59→  }
