 84→function isTextFile(name: string): boolean {
 85→  const lower = name.toLowerCase();
 86→  if (TEXT_EXTENSIONS.has(lower)) return true;
 87→  if (TEXT_FILENAMES.has(lower)) return true;
 88→  const lastDot = lower.lastIndexOf('.');
 89→  if (lastDot === -1) return false;
 90→  return TEXT_EXTENSIONS.has(lower.slice(lastDot));
 91→}
 92→
 93→/** Extensions recognized as previewable image files. */
 94→const IMAGE_EXTENSIONS = new Set([
 95→  '.png',
 96→  '.jpg',
 97→  '.jpeg',
 98→  '.gif',
 99→  '.webp',
100→  '.svg',
101→  '.bmp',
102→  '.ico',
103→  '.avif',
104→]);
105→
106→/** Extensions recognized as PDF files. */
107→const PDF_EXTENSIONS = new Set(['.pdf']);
108→
109→/** Extensions recognized as playable audio files. */
110→const AUDIO_EXTENSIONS = new Set(['.mp3', '.wav', '.ogg', '.m4a', '.flac']);
111→
112→/** Extensions recognized as playable video files. */
113→const VIDEO_EXTENSIONS = new Set(['.mp4', '.webm', '.mov', '.mkv']);
114→
115→function isImageFile(name: string): boolean {
116→  const lower = name.toLowerCase();
117→  const lastDot = lower.lastIndexOf('.');
118→  if (lastDot === -1) return false;
119→  return IMAGE_EXTENSIONS.has(lower.slice(lastDot));
120→}
121→
122→function isPdfFile(name: string): boolean {
123→  const lower = name.toLowerCase();
124→  const lastDot = lower.lastIndexOf('.');
125→  if (lastDot === -1) return false;
126→  return PDF_EXTENSIONS.has(lower.slice(lastDot));
127→}
128→
129→function isAudioFile(name: string): boolean {
130→  const lower = name.toLowerCase();
131→  const lastDot = lower.lastIndexOf('.');
132→  if (lastDot === -1) return false;
133→  return AUDIO_EXTENSIONS.has(lower.slice(lastDot));
134→}
135→
136→function isVideoFile(name: string): boolean {
137→  const lower = name.toLowerCase();
138→  const lastDot = lower.lastIndexOf('.');
139→  if (lastDot === -1) return false;
140→  return VIDEO_EXTENSIONS.has(lower.slice(lastDot));
141→}
142→
143→function isPreviewableFile(name: string): boolean {
144→  return (
145→    isImageFile(name) ||
146→    isPdfFile(name) ||
147→    isAudioFile(name) ||
148→    isVideoFile(name) ||
149→    isTextFile(name)
150→  );
151→}
152→
153→function isFilePointer(item: FolderChild): item is FilePointer {
154→  return item.type === 'file';
155→}
156→
157→/**
158→ * Truncate a public key for display: 0x{first4}...{last4}
159→ */
160→function truncatePubkey(pubkey: string): string {
161→  if (pubkey.length <= 12) return pubkey;
162→  const hex = pubkey.startsWith('0x') ? pubkey.slice(2) : pubkey;
163→  return `0x${hex.slice(0, 4)}...${hex.slice(-4)}`;
164→}
