166→/**
167→ * Sort items: folders first, then files, both alphabetically.
168→ */
169→function sortItems(items: FolderChild[]): FolderChild[] {
170→  return [...items].sort((a, b) => {
171→    if (a.type === 'folder' && b.type !== 'folder') return -1;
172→    if (a.type !== 'folder' && b.type === 'folder') return 1;
173→    return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
174→  });
175→}
