 27→/**
 28→ * Copyable value with a copy button.
 29→ * Shows the full value with word-break and a small copy button.
 30→ */
 31→function CopyableValue({ value }: { value: string }) {
 32→  const [copied, setCopied] = useState(false);
 33→  const timeoutRef = useRef<ReturnType<typeof setTimeout>>();
 34→
 35→  useEffect(() => {
 36→    return () => {
 37→      if (timeoutRef.current) clearTimeout(timeoutRef.current);
 38→    };
 39→  }, []);
 40→
 41→  const handleCopy = useCallback(async () => {
 42→    if (timeoutRef.current) clearTimeout(timeoutRef.current);
 43→    try {
 44→      await navigator.clipboard.writeText(value);
 45→    } catch {
 46→      // Fallback for older browsers
 47→      const textarea = document.createElement('textarea');
 48→      textarea.value = value;
 49→      textarea.style.position = 'fixed';
 50→      textarea.style.opacity = '0';
 51→      document.body.appendChild(textarea);
 52→      textarea.select();
 53→      document.execCommand('copy');
 54→      document.body.removeChild(textarea);
 55→    }
 56→    setCopied(true);
 57→    timeoutRef.current = setTimeout(() => setCopied(false), 2000);
 58→  }, [value]);
 59→
 60→  return (
 61→    <div className="details-copyable">
 62→      <span className="details-copyable-text">{value}</span>
 63→      <button
 64→        type="button"
 65→        className={`details-copy-btn ${copied ? 'details-copy-btn--copied' : ''}`}
 66→        onClick={handleCopy}
 67→        aria-label={copied ? 'Copied to clipboard' : 'Copy to clipboard'}
 68→        aria-pressed={copied}
 69→      >
 70→        {copied ? 'ok' : 'cp'}
 71→      </button>
 72→    </div>
 73→  );
 74→}
