 1→/**
 2→ * @cipherbox/crypto - AES-256-GCM Encryption
 3→ *
 4→ * Symmetric encryption for file content and folder metadata.
 5→ * Uses Web Crypto API for hardware-accelerated encryption.
 6→ */
 7→
 8→import { CryptoError } from '../types';
 9→import { AES_KEY_SIZE, AES_IV_SIZE, AES_GCM_ALGORITHM } from '../constants';
10→
11→/**
12→ * Encrypt data using AES-256-GCM.
13→ *
14→ * Each encryption MUST use a unique IV with the same key.
15→ * Reusing IV+key pairs is catastrophic for AES-GCM security.
16→ *
17→ * @param plaintext - Data to encrypt
18→ * @param key - 32-byte AES key
19→ * @param iv - 12-byte initialization vector (MUST be unique per encryption)
20→ * @returns Ciphertext including 16-byte authentication tag
21→ * @throws CryptoError with generic message on any failure
22→ */
23→export async function encryptAesGcm(
24→  plaintext: Uint8Array,
25→  key: Uint8Array,
26→  iv: Uint8Array
27→): Promise<Uint8Array> {
28→  // Validate key size
29→  if (key.length !== AES_KEY_SIZE) {
30→    throw new CryptoError('Encryption failed', 'INVALID_KEY_SIZE');
31→  }
32→
33→  // Validate IV size
34→  if (iv.length !== AES_IV_SIZE) {
35→    throw new CryptoError('Encryption failed', 'INVALID_IV_SIZE');
36→  }
37→
38→  try {
39→    // Copy to ensure proper ArrayBuffer (not SharedArrayBuffer)
40→    const keyBuffer = new Uint8Array(key).buffer as ArrayBuffer;
41→    const ivBuffer = new Uint8Array(iv).buffer as ArrayBuffer;
42→    const plaintextBuffer = new Uint8Array(plaintext).buffer as ArrayBuffer;
43→
44→    // Import key for encryption
