 2→//! Used by CipherBoxFS::drain_refresh_completions() which is platform-agnostic.
 3→
 4→/// Decrypt folder metadata from IPFS encrypted JSON format.
 5→pub fn decrypt_metadata_from_ipfs_public(
 6→    encrypted_bytes: &[u8],
 7→    folder_key: &[u8],
 8→) -> Result<crate::crypto::folder::FolderMetadata, String> {
 9→    #[derive(serde::Deserialize)]
10→    struct EncryptedFolderMetadata {
11→        iv: String,
12→        data: String,
13→    }
14→
15→    let encrypted: EncryptedFolderMetadata = serde_json::from_slice(encrypted_bytes)
16→        .map_err(|e| format!("Failed to parse encrypted metadata JSON: {}", e))?;
17→
18→    let iv_bytes =
19→        hex::decode(&encrypted.iv).map_err(|_| "Invalid metadata IV hex".to_string())?;
20→    if iv_bytes.len() != 12 {
21→        return Err(format!(
22→            "Invalid IV length: {} (expected 12)",
23→            iv_bytes.len()
24→        ));
25→    }
26→    let iv: [u8; 12] = iv_bytes.try_into().unwrap();
27→
28→    use base64::Engine;
29→    let ciphertext = base64::engine::general_purpose::STANDARD
30→        .decode(&encrypted.data)
31→        .map_err(|e| format!("Invalid metadata base64: {}", e))?;
32→
33→    let folder_key_arr: [u8; 32] = folder_key
34→        .try_into()
35→        .map_err(|_| "Invalid folder key length".to_string())?;
36→
37→    // Reconstruct sealed format: IV || ciphertext (includes tag)
38→    let mut sealed = Vec::with_capacity(12 + ciphertext.len());
39→    sealed.extend_from_slice(&iv);
40→    sealed.extend_from_slice(&ciphertext);
41→
42→    crate::crypto::folder::decrypt_folder_metadata(&sealed, &folder_key_arr)
43→        .map_err(|e| format!("Metadata decryption failed: {}", e))
44→}
