173→    /// since 1601-01-01). Returns 0 if the time is before the Unix epoch.
174→    fn systemtime_to_filetime(t: SystemTime) -> u64 {
175→        // Windows FILETIME epoch: 1601-01-01 00:00:00 UTC
176→        // Unix epoch: 1970-01-01 00:00:00 UTC
177→        // Difference: 11644473600 seconds = 116444736000000000 in 100ns intervals
178→        const EPOCH_DIFF: u64 = 116_444_736_000_000_000;
179→        match t.duration_since(UNIX_EPOCH) {
180→            Ok(d) => {
181→                let hundred_ns = d.as_secs() * 10_000_000 + d.subsec_nanos() as u64 / 100;
182→                hundred_ns + EPOCH_DIFF
183→            }
184→            Err(_) => 0,
185→        }
186→    }
