188→    /// Convert Windows FILETIME to SystemTime. Returns UNIX_EPOCH if invalid.
189→    fn filetime_to_systemtime(ft: u64) -> SystemTime {
190→        const EPOCH_DIFF: u64 = 116_444_736_000_000_000;
191→        if ft < EPOCH_DIFF {
192→            return UNIX_EPOCH;
193→        }
