        expect.objectContaining({
          to: 'user@example.com',
          from: 'test@cipherbox.cc',
          subject: 'Your CipherBox verification code',
          text: expect.stringContaining('verification code is:'),
          html: expect.stringContaining('verification code is:'),
        })
      );
    });

