      const sgConfigService = {
        get: jest.fn((key: string, defaultValue?: unknown) => {
          if (key === 'SENDGRID_API_KEY') return 'SG.test-api-key';
          if (key === 'SENDGRID_FROM_EMAIL') return 'test@cipherbox.cc';
