      const hashedOtp = await argon2.hash('123456');

      mockRedis.get
        .mockResolvedValueOnce(null) // verify attempts
        .mockResolvedValueOnce(hashedOtp); // stored OTP hash
      mockRedis.incr.mockResolvedValue(1);

