      mockRedis.get
        .mockResolvedValueOnce(null) // verify attempts
        .mockResolvedValueOnce(null); // no stored OTP
      mockRedis.incr.mockResolvedValue(1);

      await expect(service.verifyOtp('test@example.com', '123456')).rejects.toThrow(
